/* @lc app=leetcode id=2734 lang=kotlin */ class Solution { fun smallestString(s: String): String = s.indexOfFirst { it != 'a' }.let { f -> if (f == -1) s.dropLast(1) + 'z' else s.substring(0, f) + s.substring(f).let { r -> r.indexOfFirst { it == 'a' }.let { e -> (if (e == -1) r else r.substring(0, e)).map { (it.code - 1).toChar() }.joinToString("") + (if (e == -1) "" else r.substring(e)) } } } }